data.query:
fragment accountFields on IntegratedCarrierAccountNode {
	name
  accountNumber
  meterNumber
  phoneNumber
  integratedCarrierBillingType {
    name
    code
  }
  address {
    lines
    city
    state
    postalCode
    country
  }
}

query GetShipmentInfo($integratedCarrierShipmentId: String!, $integratedCarrierRequestTypeId: String!) {
  integratedCarrierShipment(where: {id: {_eq: $integratedCarrierShipmentId}}, first: 1, orderBy: null) {
    edges {
      node {
        id
        number
        description
        shipTo
        shipToAddress {
          lines
          city
          state
          postalCode
          country
        }
        shipFrom
        shipFromAddress {
          lines
          city
          state
          postalCode
          country
        }
        packageDefinitions
        trackingNumber
        packageLabels
        integratedCarrierConnectionConfiguration {
          id
          name
          productionConnectionId
          sandboxConnectionId
          shipperIntegratedCarrierAccount {
            ...accountFields
          }
        }
        integratedCarrierService {
          id
          name
          code
        }
        integratedCarrierBillToAccount {
          ...accountFields
        }
        integratedCarrier {
          id
          name
          requestFlows(where: {integratedCarrierRequestTypeId: {_eq: $integratedCarrierRequestTypeId}}, first: 1, orderBy: null) {
            edges {
              node {
                dataFlowId
              }
            }
          }
        }
      }
    }
  }
}

data.transform:
(
  $shipment := $state.context.request.shipment;
  $billToAccount := $shipment.integratedCarrierBillToAccount;
  $service := $shipment.integratedCarrierService;

  /* Validate required fields for shipment creation */

  /* No matching bill to found */
  $isNilOrEmpty($billToAccount)
    ? $throw("No bill to account selected for integrated carrier shipment " & $shipment.number);

  /* No matching service found */
  $isNilOrEmpty($service)
    ? $throw("No service selected for integrated carrier shipment " & $shipment.number);

  /* No packages defined */
  $isNilOrEmpty($shipment.packageDefinitions)
    ? $throw("No package definitions defined for integrated carrier shipment " & $shipment.number);

  /* No ship to defined */
  $isNilOrEmpty($shipment.shipTo)
    ? $throw("No ship to information defined for integrated carrier shipment " & $shipment.number);

  /* No ship to address defined */
  $isNilOrEmpty($shipment.shipToAddress)
    ? $throw("No ship to address defined for integrated carrier shipment " & $shipment.number);

  /* Shipment must not have already been shipped */
  $not($isNilOrEmpty($shipment.trackingNumber))
    ? $throw("Existing tracking number " & $shipment.trackingNumber & " found for shipment " & $shipment.number & "; void existing tracking number before resubmitting shipment");
)

$tryCatch(
  function() {
     $executeFlow(
      $state.context.dataFlowId,   
      $state.context.request
    )
  },
  function($error) {
    {
      "errors": [$coalesce([
        /* Server error */
        $error.jse_info.response.body.data.errors,
        /* Fallback */
        $error
      ])],
      "error": true
    }
  }
)()

