  $shipment := integratedCarrierShipment.edges[0].node;

  $carrier := $shipment.integratedCarrier;

  $connection := $shipment.integratedCarrierConnectionConfiguration;

  $shipperAccount := $connection.shipperIntegratedCarrierAccount;

  $connectionId := $state.context.parameters.sandbox 
    ? $connection.sandboxConnectionId
    : $connection.productionConnectionId;

  $dataFlowId := $carrier.requestFlows.edges.node.dataFlowId;

  /* Validate fields required for any integrated carrier request */

  /* No shipment found at all */
  $isNilOrEmpty($shipment)
    ? $throw("Integrated carrier shipment not found");

  /* No carrier found */
  $isNilOrEmpty($carrier)
    ? $throw("No carrier selected for integrated carrier shipment " & $shipment.number);

  /* No connection found */
  $isNilOrEmpty($connection)
    ? $throw("No connection selected for integrated carrier shipment " & $shipment.number);

  /* Connection found, but no sandbox connection configured */
  $isNilOrEmpty($connectionId) and $state.context.sandbox
    ? $throw("No sandbox connection configured for connection configuration " & $connection.name);

  /* No configured shipper account */
  $isNilOrEmpty($shipperAccount)
    ? $throw("No shipper account configured for connection configuration " & $connection.name);

  /* No flow configured for the request type */
  $isNilOrEmpty($dataFlowId)
    ? $throw("Carrier " & $carrier.name & " does not support the " & $state.context.parameters.integratedCarrierRequestTypeId & " action.");

  /* Return config info */

  {
    "dataFlowId": $dataFlowId,
    "request": {
      "connectionId": $connectionId,
      "sandbox": $state.context.parameters.sandbox,
      "shipment": $merge([
        $shipment,
        {
          "shipTo": $merge([
            $coalesce([$shipment.shipTo, {}]),
            {
              "address": $shipment.shipToAddress
            }
          ]),
          "shipFrom": $merge([
            $coalesce([$shipment.shipFrom, {}]),
            {
              "address": $shipment.shipFromAddress
            }
          ])
        }
      ])
    }
  }
)

